const STORAGE_KEY='mzp_config_v1',SESSION_KEY='mzp_session',DEFAULT_PASS='mizan-2026';
const DEFAULT_CONFIG={version:1,passwordHash:null,isFirstRun:true,calculations:{enabled:true,equations:{API:true,CTE:true,CFI:true,ABCE:true,EII:true,STL:true,ERI:true,CAW:true,QEI:true,SPBE:true,V30I:true,BEPI:true},setback:{street:3,neighbor:1.5},buildRatio:{small:70,medium:65,large:60,huge:50},wasteFactor:7,vatRate:15},elements:{tabs:{rating:true,design:true,boq:true},sections:{discovery:true,projectTools:true,assistant:true,roomCounts:true,roomsTable:true,alternatives:true,plan2D:true,viewer3D:true,sunStudy:true,review:true,insights:true,engineering:true,warnings:true,visualizer:true},cards:{plotCard:true,planningCard:true,ratingCard:true,insightsCard:true,visualizerCard:true}},appearance:{font:'IBM Plex Sans Arabic',fontScale:100,darkMode:false,accentColor:'#b56554'},users:[{id:'admin',name:'المدير العام',role:'admin',permissions:['all'],createdAt:new Date().toISOString()}],permissions:{canViewRatings:true,canEditCalculations:true,canExportData:true,canEditUsers:true,canChangeFonts:true,canViewAllTabs:true,canDeleteContent:true}};
let config=structuredClone(DEFAULT_CONFIG),view='overview',auth=false,failed=0,lockUntil=0;const listeners=new Map();
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function on(event,fn){if(!listeners.has(event))listeners.set(event,[]);listeners.get(event).push(fn);return()=>listeners.get(event)?.splice(listeners.get(event).indexOf(fn),1)}
function emit(event,detail){(listeners.get(event)||[]).forEach(fn=>{try{fn(detail)}catch{}});window.dispatchEvent(new CustomEvent('mizan:'+event,{detail}))}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(config));emit('config:changed',structuredClone(config));return true}catch{return false}}
function load(){try{const d=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');if(d&&typeof d==='object')config={...structuredClone(DEFAULT_CONFIG),...d,calculations:{...DEFAULT_CONFIG.calculations,...d.calculations},elements:{...DEFAULT_CONFIG.elements,...d.elements},appearance:{...DEFAULT_CONFIG.appearance,...d.appearance},permissions:{...DEFAULT_CONFIG.permissions,...d.permissions}}}catch{}}
async function hashPass(p){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(p+'_mizan_salt_v1'));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function toast(msg,type='success'){let e=document.querySelector('.mzp-toast');if(!e){e=document.createElement('div');e.className='mzp-toast';document.body.append(e)}e.textContent=msg;e.classList.toggle('error',type==='error');e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),3000)}
function ensureStyles(){if(!document.querySelector('link[data-mizan-portal]')){const l=document.createElement('link');l.rel='stylesheet';l.href='./mizan-portal.css';l.dataset.mizanPortal='';document.head.append(l)}}
function build(){if(document.getElementById('mzpRoot'))return;const r=document.createElement('div');r.id='mzpRoot';r.className='mzp-root';r.innerHTML=`<button class="mzp-fab" id="mzpFab">🔐 بوابة ميزان<span class="mzp-fab-lock">✓</span></button><div class="mzp-modal" id="mzpLogin"><div class="mzp-login-box"><div class="mzp-login-head"><div class="mzp-login-icon">🔒</div><h2>بوابة ميزان</h2><p id="mzpSub">أدخل كلمة المرور للوصول إلى لوحة التحكم</p></div><form id="mzpForm"><div class="mzp-field"><label>كلمة المرور</label><div class="mzp-pass-wrap"><input id="mzpPass" type="password" required autocomplete="current-password"><button type="button" class="mzp-pass-toggle" id="mzpToggle">◉</button></div></div><div class="mzp-error" id="mzpErr"></div><div class="mzp-login-actions"><button type="button" class="mzp-btn ghost" id="mzpCancel">إلغاء</button><button class="mzp-btn primary">دخول</button></div></form><div class="mzp-login-foot">تُحفظ الإعدادات محليًا في هذا المتصفح</div></div></div><div class="mzp-dash" id="mzpDash"><aside class="mzp-side" id="mzpSide"><div class="mzp-side-head">🏛️ بوابة ميزان<small>ADMIN CONSOLE</small></div><nav class="mzp-side-nav" id="mzpNav"></nav><div class="mzp-side-foot">● متصل<br>الإصدار 1.0</div></aside><main class="mzp-main"><header class="mzp-main-head"><div><button class="mzp-btn ghost mzp-menu-toggle" id="mzpMenu">☰</button><h1 id="mzpTitle">نظرة عامة</h1><p id="mzpSubTitle">ملخص حالة المشروع والإعدادات</p></div><div class="mzp-head-actions"><button class="mzp-btn ghost" id="mzpClose">إغلاق</button><button class="mzp-btn danger" id="mzpLogout">خروج</button></div></header><div class="mzp-body" id="mzpBody"></div></main></div>`;document.body.append(r)}
const navItems=[['overview','نظرة عامة'],['calculations','الحسابات والمعادلات'],['elements','العناصر والرسومات'],['appearance','المظهر والخطوط'],['users','المستخدمون'],['permissions','الصلاحيات'],['data','البيانات'],['security','الأمان']];
function renderNav(){const n=document.getElementById('mzpNav');n.innerHTML=navItems.map(x=>`<button class="mzp-nav-item ${view===x[0]?'on':''}" data-v="${x[0]}">${x[1]}</button>`).join('');n.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>switchView(b.dataset.v))}
function switchView(v){view=v;renderNav();const it=navItems.find(x=>x[0]===v);document.getElementById('mzpTitle').textContent=it?.[1]||'';renderView();document.getElementById('mzpSide').classList.remove('open')}
function row(label,on,attr,desc=''){return`<div class="mzp-toggle-row ${on?'on':''}" ${attr}><div class="mzp-switch"></div><div class="mzp-toggle-body"><b>${esc(label)}</b><small>${esc(desc)}</small></div></div>`}
function renderView(){const b=document.getElementById('mzpBody');let h='';if(view==='overview'){const eq=Object.values(config.calculations.equations).filter(Boolean).length,total=Object.keys(config.calculations.equations).length,sec=Object.values(config.elements.sections).filter(Boolean).length;b.innerHTML=`<div class="mzp-stats"><div class="mzp-stat"><span class="mzp-stat-label">المعادلات المفعلة</span><div class="mzp-stat-value ok">${eq}/${total}</div></div><div class="mzp-stat"><span class="mzp-stat-label">الأقسام الظاهرة</span><div class="mzp-stat-value info">${sec}/14</div></div><div class="mzp-stat"><span class="mzp-stat-label">المستخدمون</span><div class="mzp-stat-value">${config.users.length}</div></div><div class="mzp-stat"><span class="mzp-stat-label">حالة النظام</span><div class="mzp-stat-value ok">مستقر</div></div></div><div class="mzp-card"><div class="mzp-card-head"><div><h2>اختصارات سريعة</h2><p>الوصول إلى أهم الإعدادات</p></div></div><div class="mzp-action-grid">${[['calculations','ضبط الحسابات'],['elements','العناصر والرسومات'],['appearance','المظهر والخطوط'],['users','المستخدمون']].map(x=>`<button class="mzp-action" data-go="${x[0]}"><b>${x[1]}</b><small>فتح القسم</small></button>`).join('')}</div></div>`;b.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>switchView(x.dataset.go));return}
if(view==='calculations'){const eqs=Object.entries(config.calculations.equations).map(([k,v])=>row(k,v,`data-eq="${k}"`,'تمكين المعادلة الهندسية')).join('');b.innerHTML=`<div class="mzp-card"><div class="mzp-card-head"><div><h2>المعادلات الهندسية</h2><p>تمكين أو تعطيل كل معادلة</p></div></div>${row('محرك الحسابات الرئيسي',config.calculations.enabled,'data-calc="main"')}${eqs}<div class="mzp-grid-2"><div class="mzp-field"><label>ارتداد الشارع (م)</label><input id="street" type="number" value="${config.calculations.setback.street}"></div><div class="mzp-field"><label>ارتداد الجار (م)</label><input id="neighbor" type="number" value="${config.calculations.setback.neighbor}"></div><div class="mzp-field"><label>الهدر (%)</label><input id="waste" type="number" value="${config.calculations.wasteFactor}"></div><div class="mzp-field"><label>الضريبة (%)</label><input id="vat" type="number" value="${config.calculations.vatRate}"></div></div><button class="mzp-btn primary" id="saveCalc">حفظ الإعدادات</button></div>`;b.querySelector('[data-calc]').onclick=()=>{config.calculations.enabled=!config.calculations.enabled;renderView()};b.querySelectorAll('[data-eq]').forEach(x=>x.onclick=()=>{config.calculations.equations[x.dataset.eq]=!config.calculations.equations[x.dataset.eq];renderView()});b.querySelector('#saveCalc').onclick=()=>{config.calculations.setback.street=+b.querySelector('#street').value||3;config.calculations.setback.neighbor=+b.querySelector('#neighbor').value||1.5;config.calculations.wasteFactor=+b.querySelector('#waste').value||7;config.calculations.vatRate=+b.querySelector('#vat').value||15;save();toast('تم حفظ إعدادات الحسابات')};return}
if(view==='elements'){const items=Object.entries(config.elements.sections);b.innerHTML=`<div class="mzp-card"><div class="mzp-card-head"><div><h2>أقسام المشروع</h2><p>إظهار وإخفاء أقسام الواجهة</p></div></div>${items.map(([k,v])=>row(k,v,`data-sec="${k}"`)).join('')}</div>`;b.querySelectorAll('[data-sec]').forEach(x=>x.onclick=()=>{config.elements.sections[x.dataset.sec]=!config.elements.sections[x.dataset.sec];save();renderView()});return}
if(view==='appearance'){b.innerHTML=`<div class="mzp-card"><div class="mzp-card-head"><div><h2>المظهر والخطوط</h2><p>تخصيص القراءة والوضع العام</p></div></div><div class="mzp-field"><label>الخط</label><select id="font"><option>IBM Plex Sans Arabic</option><option>Tajawal</option><option>Cairo</option><option>Almarai</option></select></div><div class="mzp-field"><label>مقياس الخط (%)</label><input id="scale" type="number" min="80" max="140" value="${config.appearance.fontScale}"></div>${row('الوضع الليلي',config.appearance.darkMode,'data-dark="1"')}<button class="mzp-btn primary" id="saveApp">حفظ المظهر</button></div>`;b.querySelector('#font').value=config.appearance.font;b.querySelector('[data-dark]').onclick=()=>{config.appearance.darkMode=!config.appearance.darkMode;renderView()};b.querySelector('#saveApp').onclick=()=>{config.appearance.font=b.querySelector('#font').value;config.appearance.fontScale=+b.querySelector('#scale').value||100;save();applyAppearance();toast('تم حفظ المظهر')};return}
if(view==='users'){b.innerHTML=`<div class="mzp-card"><div class="mzp-card-head"><div><h2>المستخدمون</h2><p>الحسابات المحلية والأدوار</p></div><button class="mzp-btn primary" id="addUser">إضافة</button></div><table class="mzp-table"><thead><tr><th>الاسم</th><th>الدور</th><th>إجراء</th></tr></thead><tbody>${config.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.role)}</td><td>${u.id==='admin'?'—':`<button class="mzp-btn danger" data-del="${u.id}">حذف</button>`}</td></tr>`).join('')}</tbody></table></div>`;b.querySelector('#addUser').onclick=()=>{const name=prompt('اسم المستخدم');if(!name)return;config.users.push({id:'u_'+Date.now(),name:name.trim(),role:'editor',permissions:[],createdAt:new Date().toISOString()});save();renderView()};b.querySelectorAll('[data-del]').forEach(x=>x.onclick=()=>{config.users=config.users.filter(u=>u.id!==x.dataset.del);save();renderView()});return}
if(view==='permissions'){b.innerHTML=`<div class="mzp-card"><div class="mzp-card-head"><div><h2>الصلاحيات</h2><p>التحكم بالعمليات المتاحة</p></div></div>${Object.entries(config.permissions).map(([k,v])=>row(k,v,`data-perm="${k}"`)).join('')}<button class="mzp-btn primary" id="savePerm">حفظ الصلاحيات</button></div>`;b.querySelectorAll('[data-perm]').forEach(x=>x.onclick=()=>{config.permissions[x.dataset.perm]=!config.permissions[x.dataset.perm];x.classList.toggle('on')});b.querySelector('#savePerm').onclick=()=>{save();toast('تم حفظ الصلاحيات')};return}
if(view==='data'){b.innerHTML=`<div class="mzp-card"><div class="mzp-card-head"><div><h2>البيانات</h2><p>نسخ احتياطي محلي للإعدادات</p></div></div><div class="mzp-action-grid"><button class="mzp-action" id="export">تصدير الإعدادات</button><button class="mzp-action danger" id="reset">إعادة التعيين</button></div></div>`;b.querySelector('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({...config,passwordHash:undefined},null,2)],{type:'application/json'}));a.download='mizan-portal-config.json';a.click();toast('تم تصدير الإعدادات')};b.querySelector('#reset').onclick=()=>{if(confirm('تأكيد إعادة التعيين؟')){localStorage.removeItem(STORAGE_KEY);location.reload()}};return}
if(view==='security'){b.innerHTML=`<div class="mzp-card"><div class="mzp-card-head"><div><h2>الأمان</h2><p>تغيير كلمة مرور البوابة</p></div></div><div class="mzp-field"><label>الحالية</label><input id="old" type="password"></div><div class="mzp-field"><label>الجديدة</label><input id="new" type="password"></div><div class="mzp-field"><label>التأكيد</label><input id="new2" type="password"></div><button class="mzp-btn primary" id="change">حفظ كلمة المرور</button></div>`;b.querySelector('#change').onclick=async()=>{const [o,n,n2]=['old','new','new2'].map(id=>b.querySelector('#'+id).value);if(!o||n.length<6||n!==n2)return toast('تحقق من الحقول','error');if(await hashPass(o)!==config.passwordHash)return toast('كلمة المرور الحالية غير صحيحة','error');config.passwordHash=await hashPass(n);save();toast('تم تغيير كلمة المرور')};return}}
function applyAppearance(){document.body.style.fontSize=(16.5*(config.appearance.fontScale/100)).toFixed(1)+'px';document.body.classList.toggle('mzp-dark',config.appearance.darkMode);document.documentElement.style.setProperty('--mizan-accent',config.appearance.accentColor)}
function openLogin(){const m=document.getElementById('mzpLogin');m.classList.add('show');document.getElementById('mzpPass').focus()};function closeLogin(){document.getElementById('mzpLogin').classList.remove('show');document.getElementById('mzpForm').reset()};function openDash(){closeLogin();document.getElementById('mzpDash').classList.add('show');renderNav();switchView('overview');document.body.style.overflow='hidden'}function closeDash(){document.getElementById('mzpDash').classList.remove('show');document.body.style.overflow=''}
async function login(e){e.preventDefault();const err=document.getElementById('mzpErr');err.classList.remove('show');if(Date.now()<lockUntil){err.textContent='الحساب مقفل مؤقتًا';err.classList.add('show');return}const p=document.getElementById('mzpPass').value;if(config.isFirstRun||!config.passwordHash){if(p.length<6){err.textContent='كلمة المرور 6 أحرف على الأقل';err.classList.add('show');return}config.passwordHash=await hashPass(p);config.isFirstRun=false;save();auth=true;sessionStorage.setItem(SESSION_KEY,'1');openDash();return}if(await hashPass(p)!==config.passwordHash){failed++;err.textContent='كلمة المرور غير صحيحة';if(failed>=5){lockUntil=Date.now()+900000;failed=0;err.textContent='تم القفل 15 دقيقة'}err.classList.add('show');return}failed=0;auth=true;sessionStorage.setItem(SESSION_KEY,'1');openDash()}
export function initMizanPortal(){ensureStyles();load();applyAppearance();build();auth=sessionStorage.getItem(SESSION_KEY)==='1';document.getElementById('mzpFab').onclick=()=>auth?openDash():openLogin();document.getElementById('mzpForm').onsubmit=login;document.getElementById('mzpCancel').onclick=closeLogin;document.getElementById('mzpClose').onclick=closeDash;document.getElementById('mzpLogout').onclick=()=>{auth=false;sessionStorage.removeItem(SESSION_KEY);closeDash()};document.getElementById('mzpToggle').onclick=()=>{const x=document.getElementById('mzpPass');x.type=x.type==='password'?'text':'password'};document.getElementById('mzpMenu').onclick=()=>document.getElementById('mzpSide').classList.toggle('open');emit('portal:ready',{config});return{open:openDash,close:closeDash,logout:()=>{auth=false;sessionStorage.removeItem(SESSION_KEY);closeDash()},getConfig:()=>structuredClone(config),on}}
export default{initMizanPortal,on};
